import{_ as i,o as r,c as n,j as e,a as t,aa as a}from"./chunks/framework.BAs_AphD.js";const p="/buildary-help-preview/academy/img/nastaveni-podpisu/03.webp",m=JSON.parse('{"title":"Způsoby podpisu","description":"","frontmatter":{"title":"Způsoby podpisu","wiki":"cs:diary:signaturesetting"},"headers":[],"relativePath":"diary/signaturesetting.md","filePath":"diary/signaturesetting.md","lastUpdated":1794209661000}'),s={name:"diary/signaturesetting.md"};function d(l,o,u,v,k,c){return r(),n("div",null,[...o[0]||(o[0]=[e("h1",{id:"zpusoby-podpisu",tabindex:"-1"},[t("Způsoby podpisu "),e("a",{class:"header-anchor",href:"#zpusoby-podpisu","aria-label":'Permalink to "Způsoby podpisu"'},"​")],-1),e("p",null,"Než začnete deník podepisovat, nastavte si, čím budete podepisovat. Způsob podpisu je nastavení vašeho účtu – platí ve všech denících, ve webové i v mobilní aplikaci.",-1),e("p",null,[t("Krok za krokem: "),e("a",{href:"/buildary-help-preview/akademie/nastaveni-podpisu"},"Nastavit, čím podepisuji"),t(" v Akademii.")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/zmecOIzGCbY",title:"Video: Nastavení způsobu podpisu",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),a('<h2 id="kde-se-nastavuje" tabindex="-1">Kde se nastavuje <a class="header-anchor" href="#kde-se-nastavuje" aria-label="Permalink to &quot;Kde se nastavuje&quot;">​</a></h2><p>Klikněte na ikonu postavy vpravo nahoře a v uživatelském menu zvolte <strong>Nastavení podpisu</strong>. V okně <strong>Nastavení způsobu podepisování</strong> vyberte způsob podpisu, pod ním nastavte vzhled podpisu a potvrďte tlačítkem <strong>OK</strong>.</p><figure class="shot" style="--w:760px;"><img src="'+p+'" alt="Okno Nastavení způsobu podepisování s volbami Buildary certifikát, Kvalifikovaný certifikát, Služba společnosti První certifikační autorita a Externí aplikace" loading="lazy"></figure><p>Nastavení se ukládá na server, takže je společné pro web i mobil. Změníte ho i v mobilní aplikaci a změna platí v obou – viz <a href="/buildary-help-preview/diary/m_signing">Podepisování v mobilu</a>.</p><h2 id="ktery-zpusob-zvolit" tabindex="-1">Který způsob zvolit <a class="header-anchor" href="#ktery-zpusob-zvolit" aria-label="Permalink to &quot;Který způsob zvolit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Způsob (volba v okně)</th><th>Kde se podepisuje</th><th>Co potřebujete</th><th>Typ podpisu podle eIDAS</th><th>Vhodné pro</th></tr></thead><tbody><tr><td><a href="#buildary-certifikat">Buildary certifikát</a></td><td>na serveru Buildary, okamžitě</td><td>nic</td><td>zaručený podpis, který není založený na kvalifikovaném certifikátu – <strong>není uznávaný</strong></td><td>vyzkoušení aplikace, deníky, které nejsou vedené podle stavebního zákona</td></tr><tr><td><a href="#kvalifikovany-certifikat">Kvalifikovaný certifikát</a></td><td>na webu v desktopové aplikaci Buildary, v mobilu přímo v aplikaci</td><td>kvalifikovaný certifikát od certifikační autority</td><td>zaručený podpis založený na kvalifikovaném certifikátu nebo kvalifikovaný podpis – <strong>uznávaný</strong></td><td>deníky vedené podle stavebního zákona (doporučeno)</td></tr><tr><td><a href="#sluzba-remotesign">Služba společnosti První certifikační autorita</a></td><td>v mobilní aplikaci RemoteSign</td><td>kvalifikovaný certifikát u I.CA a aplikaci RemoteSign</td><td>kvalifikovaný podpis – <strong>uznávaný</strong></td><td>držitele certifikátu I.CA, podpis z webu i mobilu</td></tr><tr><td><a href="#externi-aplikace">Externí aplikace</a></td><td>v programu pro PDF, např. Adobe Acrobat Reader</td><td>program, který umí podepisovat PDF, a certifikát</td><td>podle použitého certifikátu</td><td>jen když máte zásadní důvod nepoužít jiný způsob</td></tr></tbody></table><h2 id="proc-uznavany-podpis" tabindex="-1">Proč uznávaný podpis <a class="header-anchor" href="#proc-uznavany-podpis" aria-label="Permalink to &quot;Proč uznávaný podpis&quot;">​</a></h2><p>Deník vedený podle stavebního zákona potřebuje uznávaný podpis. Ten vytvoříte kvalifikovaným certifikátem nebo službou RemoteSign. Podpis Buildary certifikátem je sice zaručený, ale není založený na kvalifikovaném certifikátu, a proto uznávaný není. Předpisy, ze kterých elektronický deník vychází, uvádí <a href="/buildary-help-preview/diary/#pravni-predpisy">Stavební deník – Právní předpisy</a>.</p><h2 id="buildary-certifikat" tabindex="-1">Buildary certifikát <a class="header-anchor" href="#buildary-certifikat" aria-label="Permalink to &quot;Buildary certifikát&quot;">​</a></h2><p>Nejpohodlnější způsob: nic neinstalujete, podpis proběhne na serveru a je nejrychlejší. Při zvolení této možnosti vám Buildary na serveru vygeneruje osobní podpisový certifikát.</p><p>Hodí se pro vyzkoušení Buildary a pro deníky, které nejsou vedené podle stavebního zákona. Stačí také stavbyvedoucímu podzhotovitele, který zapisuje do deníku zhotovitele, pokud stavba nevyžaduje kvalifikovaný podpis.</p><div class="info custom-block"><p class="custom-block-title">Právní váha</p><p>Podpis Buildary certifikátem je podle eIDAS <strong>zaručený podpis</strong>, není však založený na kvalifikovaném certifikátu. Nejde tedy o uznávaný podpis podle zákona.</p></div>',12),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/XEnscZvW11E",title:"Video: Podpis certifikátem Buildary",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),a('<h2 id="kvalifikovany-certifikat" tabindex="-1">Kvalifikovaný certifikát <a class="header-anchor" href="#kvalifikovany-certifikat" aria-label="Permalink to &quot;Kvalifikovaný certifikát&quot;">​</a></h2><p>Doporučený způsob pro deníky vedené podle stavebního zákona a pro vlastní deník podzhotovitele.</p><ul><li><strong>Certifikát</strong> získáte u certifikační autority, například <a href="https://www.postsignum.cz/" target="_blank" rel="noreferrer">PostSignum</a> (Česká pošta, pracoviště Czech POINT) nebo <a href="https://www.ica.cz/" target="_blank" rel="noreferrer">První certifikační autorita</a>. Certifikát PostSignum vám můžeme vydat i my v rámci prezenčního školení – napište na <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a>.</li><li>Certifikát můžete mít v počítači, v mobilu, na tokenu nebo na jiném bezpečném úložišti.</li><li><strong>Ve webové aplikaci</strong> se podepisuje v <strong>desktopové aplikaci Buildary</strong>, kterou si musíte nainstalovat do počítače. Odkaz na stažení je přímo v okně Nastavení způsobu podepisování (tlačítko <strong>Přejít na stránku ke stažení aplikace</strong>). V počítači musí být kvalifikovaný certifikát nainstalovaný.</li><li><strong>V mobilní aplikaci</strong> podepisujete přímo v aplikaci. Certifikát do mobilu nejdřív přeneste – viz <a href="/buildary-help-preview/diary/m_certificate">Certifikát v mobilu</a>.</li></ul><div class="info custom-block"><p class="custom-block-title">Právní váha</p><p>Podpis kvalifikovaným certifikátem je podle eIDAS buď <strong>zaručený podpis založený na kvalifikovaném certifikátu</strong>, nebo <strong>kvalifikovaný podpis</strong>. V obou případech jde o uznávaný podpis podle zákona.</p></div>',4),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/yraKCsEYoYc",title:"Video: Podpis kvalifikovaným certifikátem",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),a('<h2 id="sluzba-remotesign" tabindex="-1">Služba RemoteSign <a class="header-anchor" href="#sluzba-remotesign" aria-label="Permalink to &quot;Služba RemoteSign&quot;">​</a></h2><p>V okně ji najdete jako <strong>Služba společnosti První certifikační autorita</strong>. Kvalifikovaný certifikát je uložený na serveru První certifikační autority (I.CA) a podpis potvrzujete v mobilní aplikaci <strong>RemoteSign</strong>, kterou si nainstalujete. Buildary s RemoteSign komunikuje samo. Takto můžete podepisovat z webové i z mobilní aplikace Buildary.</p><p>Službu mohou využít držitelé kvalifikovaného certifikátu od I.CA, kteří si ji u I.CA zřídili.</p><div class="info custom-block"><p class="custom-block-title">Právní váha</p><p>Podpis přes RemoteSign je podle eIDAS <strong>kvalifikovaný podpis</strong>.</p></div>',4),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/qtFKkCLcz3M",title:"Video: Podpis službou RemoteSign",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),a('<h2 id="externi-aplikace" tabindex="-1">Externí aplikace <a class="header-anchor" href="#externi-aplikace" aria-label="Permalink to &quot;Externí aplikace&quot;">​</a></h2><p>Buildary připraví PDF, vy ho podepíšete mimo Buildary (například v Adobe Acrobat Readeru) a podepsaný soubor nahrajete zpět. Pro uživatele je to nejpracnější způsob, proto ho volte, jen když k tomu máte zásadní důvod. Jak postupovat, popisuje <a href="/buildary-help-preview/diary/externalappsignature">Podpis v externí aplikaci</a>.</p><p>Právní váha podpisu závisí na certifikátu, který v externí aplikaci použijete.</p><h2 id="vzhled-podpisu" tabindex="-1">Vzhled podpisu <a class="header-anchor" href="#vzhled-podpisu" aria-label="Permalink to &quot;Vzhled podpisu&quot;">​</a></h2><p>V části <strong>Nastavení vzhledu podpisu v aplikaci Buildary.online</strong> určíte, jak bude podpis vypadat v PDF. Platí pro všechny způsoby kromě externí aplikace – tam vzhled vytvoří program, ve kterém podepisujete.</p><table tabindex="0"><thead><tr><th>Volba</th><th>Co podpis obsahuje</th></tr></thead><tbody><tr><td><strong>Obrázek + text</strong> (doporučujeme)</td><td>obrázek a vaše jméno s rolí v podepisovaném deníku</td></tr><tr><td><strong>Pouze obrázek</strong></td><td>jen obrázek</td></tr><tr><td><strong>Pouze text</strong></td><td>jen jméno a roli</td></tr></tbody></table><p>Text doplňuje Buildary samo podle přihlášeného uživatele a jeho role v deníku. Jako obrázek (nejvýše 100 × 100 px) se hodí logo firmy nebo naskenovaný vlastnoruční podpis. Nahrajete ho tlačítkem <strong>Procházet</strong> nebo přetažením. Jak bude podpis vypadat, vidíte vpravo v <strong>Náhledu podpisu</strong>.</p>',7)])])}const h=i(s,[["render",d]]);export{m as __pageData,h as default};
